/* Range-for friendly view over match positions: for (size_t i : nvol::memchr_iter('\n', hay)) */
class memchr_iter {
public:
    struct sentinel {};
    class iterator {
    public:
        explicit iterator(raw::nvol_memchr_iter *it) : it_(it), cur_(raw::nvol_memchr_iter_next(it)) {}
        std::size_t operator*() const { return cur_; }
        iterator &operator++() { cur_ = raw::nvol_memchr_iter_next(it_); return *this; }
        bool operator!=(sentinel) const { return cur_ != SIZE_MAX; }
    private:
        raw::nvol_memchr_iter *it_; std::size_t cur_;
    };
    memchr_iter(std::uint8_t n1, std::span<const std::uint8_t> hay) { raw::nvol_memchr_iter_init(&it_, 1, n1, 0, 0, hay.data(), hay.size()); }
    memchr_iter(std::uint8_t n1, std::uint8_t n2, std::span<const std::uint8_t> hay) { raw::nvol_memchr_iter_init(&it_, 2, n1, n2, 0, hay.data(), hay.size()); }
    memchr_iter(std::uint8_t n1, std::uint8_t n2, std::uint8_t n3, std::span<const std::uint8_t> hay) { raw::nvol_memchr_iter_init(&it_, 3, n1, n2, n3, hay.data(), hay.size()); }
    iterator begin() { return iterator(&it_); }
    sentinel end() const { return {}; }
    std::optional<std::size_t> next() { std::size_t r = raw::nvol_memchr_iter_next(&it_); return r == SIZE_MAX ? std::nullopt : std::optional<std::size_t>(r); }
    std::optional<std::size_t> next_back() { std::size_t r = raw::nvol_memchr_iter_next_back(&it_); return r == SIZE_MAX ? std::nullopt : std::optional<std::size_t>(r); }
    std::size_t count() { return raw::nvol_memchr_iter_count(&it_); }
private:
    raw::nvol_memchr_iter it_;
};

namespace memmem {
/* memchr::memmem::Finder: build once per needle, search many haystacks. Borrows the needle. */
class Finder {
public:
    explicit Finder(std::span<const std::uint8_t> needle) { raw::nvol_memmem_finder_init(&f_, needle.data(), needle.size()); }
    std::optional<std::size_t> find(std::span<const std::uint8_t> hay) const {
        std::size_t r = raw::nvol_memmem_finder_find(&f_, hay.data(), hay.size());
        return r == SIZE_MAX ? std::nullopt : std::optional<std::size_t>(r);
    }
    /* Calls f(index) for every non-overlapping match. */
    template <class F> void for_each(std::span<const std::uint8_t> hay, F &&f) const {
        std::size_t pos = 0, step = f_.nlen ? f_.nlen : 1;
        while (pos <= hay.size()) {
            std::size_t r = raw::nvol_memmem_finder_find(&f_, hay.data() + pos, hay.size() - pos);
            if (r == SIZE_MAX) break;
            f(pos + r); pos += r + step;
        }
    }
private:
    raw::nvol_memmem_finder f_;
};
inline std::optional<std::size_t> find(std::span<const std::uint8_t> hay, std::span<const std::uint8_t> needle) {
    std::size_t r = raw::nvol_memmem(hay.data(), hay.size(), needle.data(), needle.size());
    return r == SIZE_MAX ? std::nullopt : std::optional<std::size_t>(r);
}
}  // namespace memmem

namespace packed {
struct Match { std::size_t pattern, start, end; };
/* aho_corasick::packed::Searcher (LeftmostFirst). Owns copies of the patterns. */
class Searcher {
public:
    template <class Range> static std::optional<Searcher> build(const Range &patterns) {
        std::vector<const std::uint8_t *> ptrs; std::vector<std::size_t> lens;
        for (const auto &p : patterns) {
            ptrs.push_back(reinterpret_cast<const std::uint8_t *>(std::data(p)));
            lens.push_back(std::size(p) * sizeof(*std::data(p)));
        }
        Searcher s;
        s.blob_.resize((raw::nvol_teddy_blob_size(ptrs.data(), lens.data(), ptrs.size()) + 7) / 8);
        auto *b = reinterpret_cast<std::uint8_t *>(s.blob_.data());
        raw::nvol_teddy_blob_write(b, ptrs.data(), lens.data(), ptrs.size());
        if (!raw::nvol_teddy_build(&s.t_, b)) return std::nullopt;
        return s;
    }
    Searcher(const Searcher &o) : blob_(o.blob_), t_(o.t_) { t_.blob = reinterpret_cast<const std::uint8_t *>(blob_.data()); }
    Searcher(Searcher &&o) noexcept : blob_(std::move(o.blob_)), t_(o.t_) { t_.blob = reinterpret_cast<const std::uint8_t *>(blob_.data()); }
    std::optional<Match> find_in(std::span<const std::uint8_t> hay, std::size_t start, std::size_t end) const {
        raw::nvol_teddy_match m;
        if (!raw::nvol_teddy_find_in(&t_, hay.data(), start, end, &m)) return std::nullopt;
        return Match{m.pattern, m.start, m.end};
    }
    std::optional<Match> find(std::span<const std::uint8_t> hay) const { return find_in(hay, 0, hay.size()); }
    /* Calls f(Match) for every non-overlapping leftmost-first match. */
    template <class F> void for_each(std::span<const std::uint8_t> hay, F &&f) const {
        std::size_t pos = 0;
        while (auto m = find_in(hay, pos, hay.size())) { f(*m); pos = m->end; }
    }
private:
    Searcher() = default;
    std::vector<std::uint64_t> blob_;
    raw::nvol_teddy t_{};
};
}  // namespace packed

